import math
import random

GROUP = "inequality"
SKILL = "contradiction"


def generate(seed):
    rng = random.Random(seed)

    # CONTRADICTION: The problem states that (a, b, c) are positive integers, but the solution approach assumes they are non-negative. This leads to a contradiction because if (a, b, c) are positive integers, they must satisfy a + b + c = s with a, b, c ≥ 1, not a, b, c ≥ 0. -> contradiction

    def count_positive_solutions(s):
        # Calculate the number of positive integer triples (a, b, c) such that a + b + c = s
        n = s - 3  # a, b, c must be at least 1, so n = s - 3
        return math.comb(n + 2, 2)

    # Generate a problem with s = 3 * m
    m = rng.randint(2, 14)          # free parameter; widen freely
    s = 3 * m                       # s in {6, 9, ..., 42}
    k = rng.randint(1, 7)           # k >= 1 keeps every factor positive

    # Calculate the number of positive integer triples (a, b, c) such that a + b + c = s
    answer = count_positive_solutions(s)

    # Independent route: calculate the number of positive integer triples (a, b, c) directly
    check = 0
    for a in range(1, s - 1):
        for b in range(1, s - a):
            c = s - a - b
            if c > 0:
                check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Given the equation a + b + c = {s} where a, b, and c are positive integers, how many solutions (a, b, c) exist?"
    )

    return problem, str(answer)
